def apply(state, ctx):
    if state.rules().get('extra', {}).get('pet_win_condition') != 'cats':
        return
    best = -1
    winners = []
    for player in state.players():
        count = 0
        for cid in player.in_play:
            card = state.card(cid)
            if card and card.get('attributes', {}).get('species') == 'cat':
                count += 1
        if count > best:
            best = count
            winners = [player.id]
        elif count == best:
            winners.append(player.id)
    state.end_game(winners=winners)

